sql.where:
p.deleted = 0
AND p.audit_status = 'approved'
AND p.status = 'on_sale'

    AND p.title LIKE CONCAT('%', #{query.keyword}, '%')


    AND p.category_id = #{query.categoryId}


    AND p.price >= #{query.minPrice}


    AND p.price <= #{query.maxPrice}


    AND p.quality = #{query.quality}
